/**
 * App version + user-facing update notes. GENERATED by
 * scripts/bump-version.mjs — do not edit by hand (the shape of this file is
 * part of that script's contract; check-version.mjs pins APP_VERSION to the
 * six manifest copies).
 *
 * Each note carries all shipped note languages (update-note i18n discipline,
 * 2026-10-03): dates use the YYYY.MM.DD form, and the newest entry
 * must ship every language — version-notes.test.ts enforces both. Notes ship
 * in 40 languages (NOTE_LANGS): the Traditional carrier is `zh-tw`, read by
 * zh-hk and zh-mo readers (noteText), and en-GB reads en. The region-neutral
 * Traditional row was withdrawn 2026-10-11 and its note entries dropped with
 * it — every one was a copy of that entry's zh-tw wording, which remains the
 * historical record.
 */

export const APP_VERSION = '0.1.9-beta.37';

export const NOTE_LANGS = ['en', 'zh', 'zh-tw', 'cs', 'nl', 'fr', 'he', 'ja', 'ko', 'pl', 'pt-br', 'es', 'tr', 'ar', 'az', 'bg', 'bs', 'da', 'de', 'el', 'fil', 'hi', 'hr', 'hu', 'hy', 'id', 'it', 'mk', 'mr', 'ms', 'nb', 'nn', 'ro', 'rw', 'sq', 'sr', 'sv', 'ta', 'uk', 'vi'] as const;
export type NoteLang = (typeof NOTE_LANGS)[number];

export interface VersionNote {
  version: string;
  date: string; // YYYY.MM.DD
  note: Partial<Record<NoteLang, string>> & { en: string };
}

/**
 * Note text for a UI language. Hong Kong and Macau read the Taiwan wording
 * (zh-tw is their dictionary base and the notes carrier), en-GB reads en,
 * and any missing language falls back to Simplified Chinese then English —
 * a freshly bumped note renders sensibly until its translations land.
 */
export function noteText(note: VersionNote['note'], lang: string): string {
  const byLang = note as Partial<Record<string, string>>;
  if (lang === 'zh-hk') lang = 'zh-tw';
  if (lang === 'zh-mo') lang = 'zh-tw';
  if (lang === 'en-GB') lang = 'en';
  return byLang[lang] ?? note.zh ?? note.en;
}

